import { useState, useMemo, useEffect } from 'react';
import { loadBulkIds, saveBulkIds, loadOrders, saveOrders, clearAllData } from './storage';

// ── BGMI POP ITEM TYPES ──
const POP_ITEMS = [
  { id: 'p60',   label: '60 Pop',    amount: 60 },
  { id: 'p300',  label: '300 Pop',   amount: 300 },
  { id: 'p600',  label: '600 Pop',   amount: 600 },
  { id: 'p1500', label: '1500 Pop',  amount: 1500 },
  { id: 'p3000', label: '3000 Pop',  amount: 3000 },
  { id: 'p6000', label: '6000 Pop',  amount: 6000 },
  { id: 'custom', label: 'Custom',   amount: null },
];

const TABS = ['Dashboard', 'Stock Manager', 'New Order', 'Order History'];

// ── HELPERS ──
const fmtK = (n) => {
  if (n === 0) return '0';
  if (n >= 1000) return ((n / 1000) % 1 === 0 ? n / 1000 : (n / 1000).toFixed(1)) + 'K';
  return String(n);
};
const fmtNum = (n) => Number(n).toLocaleString();
const fmtMoney = (n) => `$${Number(n).toFixed(2)}`;

// Accept: "20K", "20k", "20000", "20" (plain number = raw units, NOT K)
const parseQty = (val) => {
  const s = String(val).trim().toLowerCase();
  if (!s) return 0;
  if (s.endsWith('k')) return Math.round(parseFloat(s) * 1000);
  return Math.round(parseFloat(s));
};

const stockColor = (used, total) => {
  if (total === 0) return '#4a5278';
  const p = used / total;
  if (p >= 0.9) return '#ff4d4d';
  if (p >= 0.6) return '#ffaa00';
  return '#00e5a0';
};

// ── SMART ORDER SPLITTER ──
// Given quantity needed, figure out which bulk IDs to use (can span multiple IDs)
const splitOrder = (bulkIds, qty) => {
  let remaining = qty;
  const plan = [];
  // Sort by available stock descending
  const sorted = [...bulkIds]
    .map(b => ({ ...b, available: b.totalStock - b.usedStock }))
    .filter(b => b.available > 0)
    .sort((a, b) => b.available - a.available);

  for (const b of sorted) {
    if (remaining <= 0) break;
    const take = Math.min(b.available, remaining);
    plan.push({ id: b.id, take, pricePerUnit: b.pricePerUnit });
    remaining -= take;
  }
  return { plan, fulfilled: remaining === 0, shortfall: remaining };
};

export default function App() {
  const [bulkIds, setBulkIdsRaw] = useState([]);
  const [orders, setOrdersRaw] = useState([]);
  const [activeTab, setActiveTab] = useState('Dashboard');
  const [notif, setNotif] = useState(null);

  // New Order form
  const [customerGameId, setCustomerGameId] = useState('');
  const [selectedPopItem, setSelectedPopItem] = useState('p600');
  const [customQty, setCustomQty] = useState('');
  const [orderPreview, setOrderPreview] = useState(null);
  const [orderResult, setOrderResult] = useState(null);

  // Stock Manager
  const [showAdd, setShowAdd] = useState(false);
  const [addMode, setAddMode] = useState('range');
  const [newBulk, setNewBulk] = useState({ id: '', label: '', totalStock: '', pricePerUnit: '' });
  const [rangeForm, setRangeForm] = useState({ prefix: '', from: '', to: '', totalStock: '', pricePerUnit: '' });
  const [editBulk, setEditBulk] = useState(null);
  const [showClear, setShowClear] = useState(false);
  const [search, setSearch] = useState('');

  useEffect(() => { setBulkIdsRaw(loadBulkIds()); setOrdersRaw(loadOrders()); }, []);

  const setBulkIds = (fn) => setBulkIdsRaw(prev => { const next = typeof fn === 'function' ? fn(prev) : fn; saveBulkIds(next); return next; });
  const setOrders = (fn) => setOrdersRaw(prev => { const next = typeof fn === 'function' ? fn(prev) : fn; saveOrders(next); return next; });

  const notify = (msg, type = 'success') => { setNotif({ msg, type }); setTimeout(() => setNotif(null), 3500); };

  const stats = useMemo(() => ({
    totalStock: bulkIds.reduce((a, b) => a + b.totalStock, 0),
    usedStock: bulkIds.reduce((a, b) => a + b.usedStock, 0),
    available: bulkIds.reduce((a, b) => a + (b.totalStock - b.usedStock), 0),
    totalEarnings: orders.reduce((a, o) => a + o.earnings, 0),
  }), [bulkIds, orders]);

  // ── COMPUTE ORDER PREVIEW ──
  const getQty = () => {
    const item = POP_ITEMS.find(p => p.id === selectedPopItem);
    if (selectedPopItem === 'custom') return parseQty(customQty);
    return item ? item.amount : 0;
  };

  useEffect(() => {
    const qty = getQty();
    if (!qty || qty <= 0) { setOrderPreview(null); return; }
    const result = splitOrder(bulkIds, qty);
    setOrderPreview({ qty, ...result });
  // eslint-disable-next-line
  }, [selectedPopItem, customQty, bulkIds]);

  // ── FULFILL ORDER ──
  const handleOrder = () => {
    if (!customerGameId.trim()) { notify('Enter customer game ID.', 'error'); return; }
    const qty = getQty();
    if (!qty || qty <= 0) { notify('Select or enter a valid quantity.', 'error'); return; }
    const { plan, fulfilled } = splitOrder(bulkIds, qty);
    if (!fulfilled) { notify('Not enough total stock!', 'error'); return; }

    const totalEarnings = parseFloat(plan.reduce((a, p) => a + p.take * p.pricePerUnit, 0).toFixed(2));
    const popItem = POP_ITEMS.find(p => p.id === selectedPopItem);
    const newOrder = {
      id: `ORD-${String(orders.length + 1).padStart(4, '0')}`,
      customerGameId,
      quantity: qty,
      popItem: popItem?.label || 'Custom',
      plan,
      status: 'Fulfilled',
      date: new Date().toISOString().split('T')[0],
      earnings: totalEarnings,
    };

    // Deduct stock from each bulk ID used
    setBulkIds(prev => prev.map(b => {
      const used = plan.find(p => p.id === b.id);
      return used ? { ...b, usedStock: b.usedStock + used.take } : b;
    }));
    setOrders(prev => [newOrder, ...prev]);
    setOrderResult(newOrder);
    setCustomerGameId('');
    setCustomQty('');
    notify(`Order ${newOrder.id} fulfilled!`);
  };

  // ── ADD SINGLE ──
  const handleAddSingle = () => {
    if (!newBulk.id || !newBulk.totalStock || !newBulk.pricePerUnit) { notify('Fill all fields.', 'error'); return; }
    if (bulkIds.find(b => b.id === newBulk.id)) { notify('ID already exists.', 'error'); return; }
    const stock = parseQty(newBulk.totalStock);
    if (!stock || stock <= 0) { notify('Invalid stock.', 'error'); return; }
    setBulkIds(prev => [...prev, { id: newBulk.id, label: newBulk.label || newBulk.id, totalStock: stock, usedStock: 0, pricePerUnit: parseFloat(newBulk.pricePerUnit) }]);
    setNewBulk({ id: '', label: '', totalStock: '', pricePerUnit: '' });
    setShowAdd(false);
    notify('Bulk ID added!');
  };

  // ── ADD RANGE ──
  const handleAddRange = () => {
    const { prefix, from, to, totalStock, pricePerUnit } = rangeForm;
    if (!prefix || !from || !to || !totalStock || !pricePerUnit) { notify('Fill all range fields.', 'error'); return; }
    const fromN = parseInt(from), toN = parseInt(to);
    if (fromN > toN) { notify('"From" must be less than "To".', 'error'); return; }
    if (toN - fromN > 500) { notify('Max 500 IDs at once.', 'error'); return; }
    const stock = parseQty(totalStock);
    if (!stock || stock <= 0) { notify('Invalid stock amount.', 'error'); return; }
    const price = parseFloat(pricePerUnit);
    const newEntries = [], dupes = [];
    for (let i = fromN; i <= toN; i++) {
      const id = `${prefix}${i}`;
      if (bulkIds.find(b => b.id === id)) dupes.push(id);
      else newEntries.push({ id, label: id, totalStock: stock, usedStock: 0, pricePerUnit: price });
    }
    if (newEntries.length === 0) { notify('All IDs already exist.', 'error'); return; }
    setBulkIds(prev => [...prev, ...newEntries]);
    setRangeForm({ prefix: '', from: '', to: '', totalStock: '', pricePerUnit: '' });
    setShowAdd(false);
    notify(`✓ Added ${newEntries.length} IDs (${prefix}${fromN}–${prefix}${toN})${dupes.length ? `, skipped ${dupes.length} dupes` : ''}!`);
  };

  const handleUpdateBulk = () => {
    const stock = parseQty(editBulk.totalStock);
    setBulkIds(prev => prev.map(b => b.id === editBulk.id ? { ...b, label: editBulk.label, totalStock: stock, pricePerUnit: parseFloat(editBulk.pricePerUnit) } : b));
    setEditBulk(null); notify('Updated!');
  };

  const handleDelete = (id) => { if (window.confirm(`Delete ${id}?`)) { setBulkIds(prev => prev.filter(b => b.id !== id)); notify(`${id} deleted.`); } };

  const filteredOrders = orders.filter(o =>
    o.customerGameId.toLowerCase().includes(search.toLowerCase()) ||
    o.id.toLowerCase().includes(search.toLowerCase()) ||
    (o.bulkUsed || '').toLowerCase().includes(search.toLowerCase()) ||
    (o.plan || []).some(p => p.id.toLowerCase().includes(search.toLowerCase()))
  );

  const exportCSV = () => {
    const rows = orders.flatMap(o =>
      (o.plan || [{ id: o.bulkUsed, take: o.quantity }]).map(p =>
        `${o.id},${o.customerGameId},${o.popItem || ''},${fmtNum(o.quantity)},${p.id},${fmtNum(p.take)},${o.earnings},${o.date}`
      )
    );
    const csv = ['Order ID,Customer Game ID,Pop Item,Total Qty,Bulk ID Used,Qty from ID,Earnings,Date', ...rows].join('\n');
    const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([csv], { type: 'text/csv' }));
    a.download = `popstock_${new Date().toISOString().split('T')[0]}.csv`; a.click();
  };

  const rangeCount = rangeForm.from && rangeForm.to ? Math.max(0, parseInt(rangeForm.to || 0) - parseInt(rangeForm.from || 0) + 1) : 0;

  return (
    <div style={S.app}>
      <style>{CSS}</style>
      {notif && <div className={`notif ${notif.type === 'success' ? 'ns' : 'ne'}`}>{notif.msg}</div>}

      {/* HEADER */}
      <div style={S.header}>
        <div>
          <div style={S.logo}><span style={{ color: '#5b6fff' }}>POP</span>STOCK</div>
          <div style={S.sub}>BGMI Popularity Inventory · All data saved locally on your PC</div>
        </div>
        <button className="btn-danger-sm" onClick={() => setShowClear(true)}>🗑 Clear All Data</button>
      </div>

      {/* TABS */}
      <div style={S.tabBar}>
        {TABS.map(t => <button key={t} className={`tab-btn ${activeTab === t ? 'active' : ''}`} onClick={() => { setActiveTab(t); setOrderResult(null); }}>{t}</button>)}
      </div>

      {/* MODALS */}
      {showClear && (
        <div style={S.modal}><div style={S.modalBox}>
          <div style={{ fontSize: 18, fontWeight: 800, color: '#ff4d4d', marginBottom: 10 }}>⚠ Clear All Data?</div>
          <div style={{ color: '#9ba3cc', marginBottom: 20, fontSize: 14 }}>Permanently deletes all Bulk IDs, orders, and earnings.</div>
          <div style={{ display: 'flex', gap: 10 }}>
            <button className="btn-danger" onClick={() => { clearAllData(); setBulkIdsRaw([]); setOrdersRaw([]); setShowClear(false); notify('Cleared.'); }}>Yes, Delete Everything</button>
            <button className="btn-outline" onClick={() => setShowClear(false)}>Cancel</button>
          </div>
        </div></div>
      )}

      {editBulk && (
        <div style={S.modal}><div style={S.modalBox}>
          <div className="card-title" style={{ marginBottom: 16 }}>EDIT {editBulk.id}</div>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 14, marginBottom: 16 }}>
            {[{ key: 'label', lbl: 'LABEL' }, { key: 'totalStock', lbl: 'TOTAL STOCK (e.g. 15K)' }, { key: 'pricePerUnit', lbl: 'PRICE/UNIT ($)' }].map(f => (
              <div key={f.key}><div className="lbl">{f.lbl}</div><input value={editBulk[f.key]} onChange={e => setEditBulk(p => ({ ...p, [f.key]: e.target.value }))} /></div>
            ))}
          </div>
          <div style={{ display: 'flex', gap: 10 }}>
            <button className="btn-primary" onClick={handleUpdateBulk}>Update</button>
            <button className="btn-outline" onClick={() => setEditBulk(null)}>Cancel</button>
          </div>
        </div></div>
      )}

      <div style={S.content}>

        {/* ══ DASHBOARD ══ */}
        {activeTab === 'Dashboard' && (<div>
          <div style={S.statsGrid}>
            {[
              { lbl: 'TOTAL STOCK', val: fmtK(stats.totalStock), icon: '📦', col: '#5b6fff' },
              { lbl: 'AVAILABLE', val: fmtK(stats.available), icon: '✅', col: '#00e5a0' },
              { lbl: 'USED STOCK', val: fmtK(stats.usedStock), icon: '📤', col: '#ffaa00' },
              { lbl: 'TOTAL EARNINGS', val: fmtMoney(stats.totalEarnings), icon: '💰', col: '#ff4d4d' },
            ].map(s => (
              <div key={s.lbl} className="stat-card">
                <div style={{ fontSize: 26, marginBottom: 8 }}>{s.icon}</div>
                <div className="lbl">{s.lbl}</div>
                <div style={{ fontSize: 26, fontWeight: 800, color: s.col, fontFamily: 'Space Mono,monospace' }}>{s.val}</div>
              </div>
            ))}
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: '1.4fr 1fr', gap: 20 }}>
            <div className="card">
              <div className="card-title">BULK ID STOCK ({bulkIds.length} IDs)</div>
              {bulkIds.length === 0 && <div className="empty-msg">No Bulk IDs yet. Go to Stock Manager to add.</div>}
              {bulkIds.slice(0, 12).map(b => {
                const avail = b.totalStock - b.usedStock;
                const pct = b.totalStock > 0 ? b.usedStock / b.totalStock : 0;
                const col = stockColor(b.usedStock, b.totalStock);
                return (<div key={b.id} style={{ marginBottom: 14 }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 4 }}>
                    <span className="mono" style={{ color: '#5b6fff', fontWeight: 700, fontSize: 12 }}>{b.id}</span>
                    <span className="mono" style={{ fontSize: 11 }}><span style={{ color: col }}>{fmtK(avail)}</span><span style={{ color: '#2a3050' }}> / {fmtK(b.totalStock)}</span></span>
                  </div>
                  <div className="progress-bar"><div style={{ height: '100%', width: `${pct * 100}%`, background: col, borderRadius: 3 }} /></div>
                </div>);
              })}
              {bulkIds.length > 12 && <div className="empty-msg">+{bulkIds.length - 12} more → Stock Manager</div>}
            </div>
            <div className="card">
              <div className="card-title">RECENT ORDERS</div>
              {orders.length === 0 && <div className="empty-msg">No orders yet.</div>}
              {orders.slice(0, 6).map(o => (
                <div key={o.id} style={S.orderRow}>
                  <div>
                    <div className="mono" style={{ color: '#5b6fff', fontSize: 11, fontWeight: 700 }}>{o.id}</div>
                    <div style={{ fontSize: 12, color: '#6b7299', marginTop: 2 }}>{o.customerGameId}</div>
                    <div style={{ fontSize: 11, color: '#4a5278', marginTop: 1 }}>{o.popItem}</div>
                  </div>
                  <div style={{ textAlign: 'right' }}>
                    <div className="mono" style={{ color: '#00e5a0', fontSize: 13 }}>{fmtMoney(o.earnings)}</div>
                    <div className="mono" style={{ fontSize: 11, color: '#2a3050' }}>{fmtNum(o.quantity)} pop</div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>)}

        {/* ══ STOCK MANAGER ══ */}
        {activeTab === 'Stock Manager' && (<div>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
            <div className="page-title">MANAGE BULK IDS ({bulkIds.length} total · {fmtK(stats.available)} available)</div>
            <button className="btn-primary" onClick={() => setShowAdd(!showAdd)}>+ Add Bulk IDs</button>
          </div>

          {showAdd && (
            <div className="card" style={{ marginBottom: 20 }}>
              <div style={{ display: 'flex', gap: 8, marginBottom: 18 }}>
                <button className={addMode === 'range' ? 'btn-primary' : 'btn-outline'} onClick={() => setAddMode('range')}>📦 Bulk Range</button>
                <button className={addMode === 'single' ? 'btn-primary' : 'btn-outline'} onClick={() => setAddMode('single')}>➕ Single ID</button>
                <span style={{ color: '#4a5278', fontSize: 12, fontFamily: 'Space Mono,monospace', alignSelf: 'center', marginLeft: 8 }}>
                  {addMode === 'range' ? 'Add e.g. vivopop1–vivopop100 all at once' : 'Add one Bulk ID'}
                </span>
              </div>

              {addMode === 'range' && (<div>
                <div style={{ background: '#0d1020', border: '1px solid #1a2040', borderRadius: 10, padding: '10px 16px', marginBottom: 16 }}>
                  <span style={{ color: '#4a5278', fontSize: 12, fontFamily: 'Space Mono,monospace' }}>Preview: </span>
                  <span className="mono" style={{ color: '#5b6fff', fontSize: 13 }}>
                    {rangeForm.prefix || 'vivopop'}{rangeForm.from || '1'} → {rangeForm.prefix || 'vivopop'}{rangeForm.to || '100'}
                    {rangeForm.totalStock ? ` · ${String(rangeForm.totalStock).toUpperCase()} each` : ''}
                    {rangeCount > 0 ? ` · ${rangeCount} IDs total` : ''}
                  </span>
                </div>
                <div style={{ display: 'grid', gridTemplateColumns: '1.2fr 0.6fr 0.6fr 1fr 1fr', gap: 14, marginBottom: 14 }}>
                  {[
                    { key: 'prefix', lbl: 'PREFIX', ph: 'vivopop' },
                    { key: 'from', lbl: 'FROM #', ph: '1' },
                    { key: 'to', lbl: 'TO #', ph: '100' },
                    { key: 'totalStock', lbl: 'STOCK EACH (e.g. 15K)', ph: '15000 or 15K' },
                    { key: 'pricePerUnit', lbl: 'PRICE/UNIT ($)', ph: '0.05' },
                  ].map(f => (
                    <div key={f.key}><div className="lbl">{f.lbl}</div><input value={rangeForm[f.key]} onChange={e => setRangeForm(p => ({ ...p, [f.key]: e.target.value }))} placeholder={f.ph} /></div>
                  ))}
                </div>
                <div style={{ display: 'flex', gap: 10 }}>
                  <button className="btn-primary" onClick={handleAddRange}>Add {rangeCount > 0 ? rangeCount : ''} IDs</button>
                  <button className="btn-outline" onClick={() => setShowAdd(false)}>Cancel</button>
                </div>
              </div>)}

              {addMode === 'single' && (<div>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr 1fr', gap: 14, marginBottom: 14 }}>
                  {[
                    { key: 'id', lbl: 'BULK ID', ph: 'vivopop101' },
                    { key: 'label', lbl: 'LABEL (optional)', ph: 'Pack Name' },
                    { key: 'totalStock', lbl: 'STOCK (e.g. 15K)', ph: '15000 or 15K' },
                    { key: 'pricePerUnit', lbl: 'PRICE/UNIT ($)', ph: '0.05' },
                  ].map(f => (
                    <div key={f.key}><div className="lbl">{f.lbl}</div><input value={newBulk[f.key]} onChange={e => setNewBulk(p => ({ ...p, [f.key]: e.target.value }))} placeholder={f.ph} /></div>
                  ))}
                </div>
                <div style={{ display: 'flex', gap: 10 }}>
                  <button className="btn-primary" onClick={handleAddSingle}>Save</button>
                  <button className="btn-outline" onClick={() => setShowAdd(false)}>Cancel</button>
                </div>
              </div>)}
            </div>
          )}

          <div className="card">
            <table className="tbl">
              <thead><tr><th>BULK ID</th><th>TOTAL</th><th>USED</th><th>AVAILABLE</th><th>$/UNIT</th><th>STATUS</th><th>ACTIONS</th></tr></thead>
              <tbody>
                {bulkIds.length === 0 && <tr><td colSpan={7} style={{ color: '#4a5278', textAlign: 'center', padding: 20 }}>No Bulk IDs yet. Click "+ Add Bulk IDs" above.</td></tr>}
                {bulkIds.map(b => {
                  const avail = b.totalStock - b.usedStock;
                  const pct = b.totalStock > 0 ? b.usedStock / b.totalStock : 0;
                  const col = stockColor(b.usedStock, b.totalStock);
                  const bc = pct >= 0.9 ? 'badge-red' : pct >= 0.6 ? 'badge-yellow' : 'badge-green';
                  const status = pct >= 0.9 ? 'LOW' : pct >= 0.6 ? 'MID' : 'OK';
                  return (<tr key={b.id}>
                    <td><span className="mono" style={{ color: '#5b6fff', fontWeight: 700 }}>{b.id}</span></td>
                    <td className="mono">{fmtK(b.totalStock)}</td>
                    <td className="mono" style={{ color: '#ffaa00' }}>{fmtK(b.usedStock)}</td>
                    <td className="mono" style={{ color: col, fontWeight: 700 }}>{fmtK(avail)}</td>
                    <td className="mono" style={{ color: '#00e5a0' }}>${b.pricePerUnit}</td>
                    <td><span className={`badge ${bc}`}>{status}</span></td>
                    <td><div style={{ display: 'flex', gap: 6 }}>
                      <button className="btn-sm" onClick={() => setEditBulk({ ...b, totalStock: String(b.totalStock) })}>Edit</button>
                      <button className="btn-sm-danger" onClick={() => handleDelete(b.id)}>Del</button>
                    </div></td>
                  </tr>);
                })}
              </tbody>
            </table>
          </div>
        </div>)}

        {/* ══ NEW ORDER ══ */}
        {activeTab === 'New Order' && (<div style={{ maxWidth: 680 }}>
          <div className="page-title" style={{ marginBottom: 20 }}>FULFILL CUSTOMER ORDER</div>

          <div className="card">
            {/* Customer ID */}
            <div style={{ marginBottom: 18 }}>
              <div className="lbl">CUSTOMER IN-GAME ID (BGMI UID)</div>
              <input value={customerGameId} onChange={e => setCustomerGameId(e.target.value)} placeholder="e.g. 5438272758" />
            </div>

            {/* BGMI Pop Item Selector */}
            <div style={{ marginBottom: 18 }}>
              <div className="lbl" style={{ marginBottom: 10 }}>SELECT POP ITEM TYPE</div>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 8 }}>
                {POP_ITEMS.map(item => (
                  <button
                    key={item.id}
                    onClick={() => { setSelectedPopItem(item.id); setCustomQty(''); }}
                    style={{
                      background: selectedPopItem === item.id ? 'linear-gradient(135deg,#5b6fff,#8b5cf6)' : '#0d1020',
                      border: selectedPopItem === item.id ? '1.5px solid #5b6fff' : '1.5px solid #1e2540',
                      color: selectedPopItem === item.id ? '#fff' : '#9ba3cc',
                      borderRadius: 10, padding: '12px 8px', cursor: 'pointer',
                      fontFamily: 'Space Mono,monospace', fontSize: 12, fontWeight: 700,
                      transition: 'all 0.15s', textAlign: 'center',
                    }}
                  >
                    <div style={{ fontSize: 16, marginBottom: 4 }}>🎮</div>
                    {item.label}
                    {item.amount && <div style={{ fontSize: 10, opacity: 0.7, marginTop: 2 }}>{fmtNum(item.amount)} pop</div>}
                  </button>
                ))}
              </div>
            </div>

            {/* Custom quantity input */}
            {selectedPopItem === 'custom' && (
              <div style={{ marginBottom: 18 }}>
                <div className="lbl">CUSTOM QUANTITY (e.g. 1500, 15K)</div>
                <input value={customQty} onChange={e => setCustomQty(e.target.value)} placeholder="Type amount, e.g. 1500 or 15K" autoFocus />
              </div>
            )}

            {/* ORDER PLAN PREVIEW */}
            <div style={{ background: '#0d1020', border: '1px solid #1a2040', borderRadius: 12, padding: 18, marginBottom: 18 }}>
              <div className="lbl" style={{ marginBottom: 12 }}>📋 ORDER FULFILLMENT PLAN</div>

              {!orderPreview && (
                <div className="empty-msg">Select a pop item above to see the plan.</div>
              )}

              {orderPreview && !orderPreview.fulfilled && (
                <div>
                  <div style={{ color: '#ff4d4d', fontFamily: 'Space Mono,monospace', fontSize: 13, marginBottom: 8 }}>
                    ⚠ Total available stock ({fmtNum(stats.available)}) is less than {fmtNum(orderPreview.qty)} needed.
                  </div>
                  <div style={{ color: '#4a5278', fontSize: 12, fontFamily: 'Space Mono,monospace' }}>
                    Shortfall: {fmtNum(orderPreview.shortfall)} pop. Add more Bulk IDs in Stock Manager.
                  </div>
                  {orderPreview.plan.length > 0 && (
                    <div style={{ marginTop: 10 }}>
                      <div className="lbl" style={{ marginBottom: 6 }}>PARTIAL PLAN (what's available):</div>
                      {orderPreview.plan.map(p => (
                        <div key={p.id} style={S.planRow}>
                          <span className="mono" style={{ color: '#5b6fff' }}>{p.id}</span>
                          <span className="mono" style={{ color: '#ffaa00' }}>send {fmtNum(p.take)} pop</span>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              )}

              {orderPreview && orderPreview.fulfilled && (
                <div>
                  <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 14 }}>
                    <div>
                      <div className="lbl">TOTAL QUANTITY</div>
                      <div className="mono" style={{ color: '#e8eaf0', fontSize: 15 }}>{fmtNum(orderPreview.qty)} pop</div>
                    </div>
                    <div>
                      <div className="lbl">IDS NEEDED</div>
                      <div className="mono" style={{ color: '#e8eaf0', fontSize: 15 }}>{orderPreview.plan.length}</div>
                    </div>
                    <div>
                      <div className="lbl">EST. EARNINGS</div>
                      <div className="mono" style={{ color: '#00e5a0', fontSize: 15 }}>
                        {fmtMoney(orderPreview.plan.reduce((a, p) => a + p.take * p.pricePerUnit, 0))}
                      </div>
                    </div>
                  </div>

                  <div className="lbl" style={{ marginBottom: 8 }}>SEND FROM THESE IDs:</div>
                  {orderPreview.plan.map((p, i) => (
                    <div key={p.id} style={{ ...S.planRow, background: i % 2 === 0 ? '#111420' : 'transparent' }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                        <span style={{ color: '#4a5278', fontSize: 11, fontFamily: 'Space Mono,monospace', minWidth: 20 }}>#{i + 1}</span>
                        <span className="mono" style={{ color: '#5b6fff', fontWeight: 700 }}>{p.id}</span>
                      </div>
                      <div style={{ display: 'flex', gap: 20, alignItems: 'center' }}>
                        <span>
                          <span className="lbl" style={{ marginBottom: 0, marginRight: 6 }}>SEND:</span>
                          <span className="mono" style={{ color: '#00e5a0', fontWeight: 700 }}>{fmtNum(p.take)} pop</span>
                        </span>
                        <span>
                          <span className="lbl" style={{ marginBottom: 0, marginRight: 6 }}>EARN:</span>
                          <span className="mono" style={{ color: '#ffaa00' }}>{fmtMoney(p.take * p.pricePerUnit)}</span>
                        </span>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>

            <button className="btn-primary btn-full" onClick={handleOrder}
              disabled={!orderPreview || !orderPreview.fulfilled}
              style={{ opacity: (!orderPreview || !orderPreview.fulfilled) ? 0.4 : 1, cursor: (!orderPreview || !orderPreview.fulfilled) ? 'not-allowed' : 'pointer' }}>
              ⚡ CONFIRM & FULFILL ORDER
            </button>
          </div>

          {/* ORDER RESULT */}
          {orderResult && (
            <div className="card" style={{ borderColor: '#00e5a030' }}>
              <div className="mono" style={{ color: '#00e5a0', fontWeight: 700, fontSize: 14, marginBottom: 16 }}>✓ ORDER SAVED — {orderResult.id}</div>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 14, marginBottom: 16 }}>
                <div><div className="lbl">CUSTOMER</div><div className="mono" style={{ fontSize: 14 }}>{orderResult.customerGameId}</div></div>
                <div><div className="lbl">POP ITEM</div><div className="mono" style={{ fontSize: 14, color: '#8b5cf6' }}>{orderResult.popItem}</div></div>
                <div><div className="lbl">TOTAL EARNINGS</div><div className="mono" style={{ fontSize: 14, color: '#00e5a0' }}>{fmtMoney(orderResult.earnings)}</div></div>
              </div>
              <div className="lbl" style={{ marginBottom: 8 }}>SENT FROM:</div>
              {orderResult.plan.map(p => (
                <div key={p.id} style={S.planRow}>
                  <span className="mono" style={{ color: '#5b6fff', fontWeight: 700 }}>{p.id}</span>
                  <span className="mono" style={{ color: '#00e5a0' }}>{fmtNum(p.take)} pop sent</span>
                </div>
              ))}
            </div>
          )}
        </div>)}

        {/* ══ ORDER HISTORY ══ */}
        {activeTab === 'Order History' && (<div>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
            <div className="page-title">{orders.length} TOTAL ORDERS</div>
            <div style={{ display: 'flex', gap: 10, alignItems: 'center' }}>
              <input style={{ width: 240 }} value={search} onChange={e => setSearch(e.target.value)} placeholder="Search orders..." />
              <button className="btn-outline" onClick={exportCSV}>⬇ Export CSV</button>
            </div>
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 16, marginBottom: 20 }}>
            {[
              { lbl: 'TOTAL ORDERS', val: orders.length, col: '#5b6fff' },
              { lbl: 'TOTAL EARNED', val: fmtMoney(stats.totalEarnings), col: '#00e5a0' },
              { lbl: 'TOTAL POP SOLD', val: fmtNum(orders.reduce((a, o) => a + o.quantity, 0)), col: '#ffaa00' },
            ].map(s => (<div key={s.lbl} className="stat-card"><div className="lbl">{s.lbl}</div><div style={{ fontSize: 22, fontWeight: 800, color: s.col, fontFamily: 'Space Mono,monospace' }}>{s.val}</div></div>))}
          </div>

          <div className="card">
            <table className="tbl">
              <thead><tr><th>ORDER ID</th><th>CUSTOMER ID</th><th>POP ITEM</th><th>QUANTITY</th><th>BULK IDs USED</th><th>EARNINGS</th><th>DATE</th></tr></thead>
              <tbody>
                {filteredOrders.length === 0 && <tr><td colSpan={7} style={{ color: '#4a5278', textAlign: 'center', padding: 20 }}>No orders found.</td></tr>}
                {filteredOrders.map(o => (
                  <tr key={o.id}>
                    <td><span className="mono" style={{ color: '#5b6fff', fontWeight: 700 }}>{o.id}</span></td>
                    <td style={{ color: '#9ba3cc' }}>{o.customerGameId}</td>
                    <td><span className="badge badge-purple">{o.popItem || '-'}</span></td>
                    <td className="mono">{fmtNum(o.quantity)}</td>
                    <td>
                      {(o.plan || [{ id: o.bulkUsed, take: o.quantity }]).map(p => (
                        <div key={p.id} style={{ marginBottom: 2 }}>
                          <span className="mono" style={{ color: '#5b6fff', fontSize: 11 }}>{p.id}</span>
                          <span className="mono" style={{ color: '#4a5278', fontSize: 11 }}> · {fmtNum(p.take)}</span>
                        </div>
                      ))}
                    </td>
                    <td><span className="mono" style={{ color: '#00e5a0' }}>{fmtMoney(o.earnings)}</span></td>
                    <td className="mono" style={{ color: '#4a5278' }}>{o.date}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>)}

      </div>
    </div>
  );
}

const S = {
  app: { minHeight: '100vh', background: '#0a0c14', color: '#e8eaf0', fontFamily: "'Syne','Trebuchet MS',sans-serif" },
  header: { padding: '20px 32px', borderBottom: '1px solid #1a2040', display: 'flex', alignItems: 'center', justifyContent: 'space-between' },
  logo: { fontSize: 24, fontWeight: 800, color: '#fff', letterSpacing: '-0.02em' },
  sub: { fontSize: 11, color: '#4a5278', fontFamily: 'Space Mono,monospace', marginTop: 2 },
  tabBar: { padding: '0 32px', borderBottom: '1px solid #1a2040', display: 'flex', gap: 4 },
  content: { padding: '28px 32px', maxWidth: 1200, margin: '0 auto' },
  statsGrid: { display: 'grid', gridTemplateColumns: 'repeat(4,1fr)', gap: 16, marginBottom: 24 },
  orderRow: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12, paddingBottom: 12, borderBottom: '1px solid #1a2040' },
  planRow: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '10px 12px', borderRadius: 8, marginBottom: 4 },
  modal: { position: 'fixed', inset: 0, background: '#000000aa', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 999 },
  modalBox: { background: '#111420', border: '1px solid #1a2040', borderRadius: 16, padding: 28, minWidth: 420 },
};

